from collections import deque
def comps(g, val=1):
    h,w=len(g),len(g[0]); seen=set(); out=[]
    for i in range(h):
        for j in range(w):
            if g[i][j]==val and (i,j) not in seen:
                q=deque([(i,j)]); seen.add((i,j)); c=[]
                while q:
                    y,x=q.popleft(); c.append((y,x))
                    for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<h and 0<=nx<w and g[ny][nx]==val and (ny,nx) not in seen:
                            seen.add((ny,nx)); q.append((ny,nx))
                out.append(sorted(c))
    return out
